recipes.code:
{
  "inputs": [
    {
      "id": "meertrack-api-key",
      "type": "promptString",
      "description": "Meertrack production API key (mt_live_…). Mint at Settings → API Keys.",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@meertrack/mcp@2.1.0"
      ],
      "env": {
        "MEERTRACK_API_KEY": "${input:meertrack-api-key}",
        "MEERTRACK_API_BASE_URL": "<meertrack-api-base-url>"
      }
    }
  }
}
